 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    # The uniform separator splits equal-sized panels; retain cells occupied in both.
    for c in range(w):
        if all(grid[r][c] == grid[0][c] for r in range(h)):
            left = [row[:c] for row in grid]
            right = [row[c + 1:] for row in grid]
            if left and len(left[0]) == len(right[0]):
                return [[2 if a != 0 and b != 0 else 0 for a, b in zip(x, y)] for x, y in zip(left, right)]
    for r in range(h):
        if all(v == grid[r][0] for v in grid[r]):
            top, bottom = grid[:r], grid[r + 1:]
            if len(top) == len(bottom):
                return [[2 if a != 0 and b != 0 else 0 for a, b in zip(x, y)] for x, y in zip(top, bottom)]
    raise ValueError('No equal-sized panels separated by a uniform line')

